	pg_catalog.setval ('"public"."languages_id_seq"', 15, true);

-- Backfill user_permissions for seed-created auth users (e.g. local dev seed).
-- Normally the on_auth_user_created trigger handles this; kept idempotent.
INSERT INTO
	"public"."user_permissions" ("user_id", "role")
SELECT
	"id",
	'user'
FROM
	"auth"."users" ON CONFLICT ("user_id") DO NOTHING;
